from pathlib import Path
from typing import Any

import joblib

RAIZ = Path(__file__).resolve().parent.parent
RUTA_MODELO = RAIZ / "models" / "precio_v1.joblib"


def cargar_modelo(ruta: Path = RUTA_MODELO) -> Any:
    """Devuelve el pipeline serializado. Falla pronto si el archivo no existe."""
    if not ruta.exists():
        raise FileNotFoundError(
            f"No se encontró el modelo en {ruta}. Ejecuta scripts/entrenar.py primero."
        )
    return joblib.load(ruta)

from contextlib import asynccontextmanager
from typing import Any, AsyncIterator

import pandas as pd
from fastapi import FastAPI, HTTPException

from api.esquemas import Departamento, Prediccion
from api.modelo import cargar_modelo

VERSION = "1.0.0"
modelo: Any | None = None


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    global modelo
    modelo = cargar_modelo()          # una sola vez, al arrancar
    yield
    modelo = None                     # liberar al apagar


app = FastAPI(
    title="API de precios de alquiler",
    version=VERSION,
    lifespan=lifespan,
)


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok" if modelo is not None else "sin_modelo"}


@app.post("/predict", response_model=Prediccion)
def predecir(departamento: Departamento) -> Prediccion:
    if modelo is None:
        raise HTTPException(status_code=503, detail="El modelo no está cargado")

    entrada = pd.DataFrame([departamento.model_dump()])

    try:
        precio = float(modelo.predict(entrada)[0])
    except Exception as error:  # el detalle va al log, no al cliente
        raise HTTPException(
            status_code=500, detail="No se pudo calcular la predicción"
        ) from error

    return Prediccion(precio_usd=round(precio, 2), modelo_version=VERSION)

import pandas as pd

def predecir(modelo, datos: dict) -> dict:
    entrada = pd.DataFrame([datos])
    matriz = modelo.named_steps["prep"].transform(entrada)
    precio = modelo.named_steps["reg"].predict(matriz)[0]
    return {"precio_usd": round(float(precio), 2)}

