from fastapi import HTTPException
from pydantic import BaseModel, ConfigDict, Field


class LoteEntrada(BaseModel):
    model_config = ConfigDict(extra="forbid")
    items: list[Departamento] = Field(min_length=1, max_length=50)


class LoteSalida(BaseModel):
    predicciones: list[float]
    modelo_version: str


@app.post("/predict/lote", response_model=LoteSalida)
def predecir_lote(lote: LoteEntrada) -> LoteSalida:
    if modelo is None:
        raise HTTPException(status_code=503, detail="El modelo no está cargado")

    filas = [item.model_dump() for item in lote.items]
    precios = modelo.predict(pd.DataFrame(filas))

    return LoteSalida(
        predicciones=[round(float(p), 2) for p in precios],
        modelo_version=VERSION,
    )

